-- Project Management SaaS (ProjectPro) — Complete MySQL Schema (MySQL 8+, utf8mb4)
-- Demo password for all seeded users: password
-- Hash below is a PHP password_hash()/bcrypt hash of "password" (verifiable with password_verify).
CREATE DATABASE IF NOT EXISTS project_saas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE project_saas;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,activities,notifications,support_tickets,announcements,settings,password_resets,events,time_logs,milestones,invites,team_members,teams,task_comments,task_labels,tasks,project_members,projects,invoices,payments,subscriptions,coupons,plans,role_permissions,permissions,roles,users,tenants;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE tenants (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, status ENUM('active','suspended') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tenants_status(status)) ENGINE=InnoDB;
CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE, label VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('super_admin','tenant_admin','manager','employee') NOT NULL DEFAULT 'employee', status ENUM('active','suspended') NOT NULL DEFAULT 'active', two_factor_secret VARCHAR(120) NULL, remember_token VARCHAR(64) NULL, email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_users_tenant(tenant_id), CONSTRAINT fk_users_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE password_resets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, token VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_pr_email(email), INDEX idx_pr_token(token)) ENGINE=InnoDB;
CREATE TABLE plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, price_monthly DECIMAL(10,2) NOT NULL DEFAULT 0, price_yearly DECIMAL(10,2) NOT NULL DEFAULT 0, max_users INT NOT NULL DEFAULT 3, max_projects INT NOT NULL DEFAULT 3, max_tasks INT NOT NULL DEFAULT 100, features TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, plan_id INT UNSIGNED NOT NULL, status ENUM('trial','active','past_due','cancelled','expired') NOT NULL DEFAULT 'trial', billing_cycle ENUM('monthly','yearly') NOT NULL DEFAULT 'monthly', starts_at DATETIME NULL, ends_at DATETIME NULL, trial_ends_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_sub_tenant(tenant_id), CONSTRAINT fk_sub_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_sub_plan FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB;
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, subscription_id INT UNSIGNED NULL, amount DECIMAL(12,2) NOT NULL, status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending', method VARCHAR(40) NULL, transaction_ref VARCHAR(120) NULL, paid_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_pay_tenant(tenant_id), CONSTRAINT fk_pay_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_pay_sub FOREIGN KEY(subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE invoices (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, payment_id INT UNSIGNED NULL, invoice_number VARCHAR(40) NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, status ENUM('draft','paid','overdue','cancelled') NOT NULL DEFAULT 'draft', issued_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_inv_tenant(tenant_id), CONSTRAINT fk_inv_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_inv_pay FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE coupons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, discount_percent INT NOT NULL DEFAULT 10, max_uses INT NOT NULL DEFAULT 100, used_count INT NOT NULL DEFAULT 0, expires_at DATETIME NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, description TEXT NULL, start_date DATE NULL, end_date DATE NULL, budget DECIMAL(12,2) NOT NULL DEFAULT 0, category VARCHAR(60) NOT NULL DEFAULT 'general', priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium', status ENUM('planning','active','on_hold','completed','archived') NOT NULL DEFAULT 'active', progress INT NOT NULL DEFAULT 0, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_proj_tenant(tenant_id), INDEX idx_proj_status(status), CONSTRAINT fk_proj_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_proj_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE project_members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, project_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, role_in_project VARCHAR(60) NOT NULL DEFAULT 'member', UNIQUE KEY uq_pm (project_id,user_id), INDEX idx_pm_tenant(tenant_id), CONSTRAINT fk_pm_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_pm_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_pm_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, project_id INT UNSIGNED NULL, title VARCHAR(180) NOT NULL, description TEXT NULL, assigned_to INT UNSIGNED NULL, created_by INT UNSIGNED NULL, priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium', status ENUM('todo','in_progress','review','done') NOT NULL DEFAULT 'todo', due_date DATE NULL, labels VARCHAR(255) NULL, depends_on INT UNSIGNED NULL, is_recurring TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_task_tenant(tenant_id), INDEX idx_task_project(project_id), INDEX idx_task_status(status), CONSTRAINT fk_task_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_task_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_task_user FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_task_depends FOREIGN KEY(depends_on) REFERENCES tasks(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE task_comments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, task_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tc_task(task_id), CONSTRAINT fk_tc_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_tc_task FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE, CONSTRAINT fk_tc_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE task_labels (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(60) NOT NULL, color VARCHAR(20) NULL, UNIQUE KEY uq_label (tenant_id,name), CONSTRAINT fk_label_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE teams (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, description TEXT NULL, leader_id INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_team_tenant(tenant_id), CONSTRAINT fk_team_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_team_leader FOREIGN KEY(leader_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE team_members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, team_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, role_in_team VARCHAR(60) NOT NULL DEFAULT 'member', UNIQUE KEY uq_tm (team_id,user_id), INDEX idx_tm_tenant(tenant_id), CONSTRAINT fk_tm_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_tm_team FOREIGN KEY(team_id) REFERENCES teams(id) ON DELETE CASCADE, CONSTRAINT fk_tm_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE invites (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, team_id INT UNSIGNED NULL, email VARCHAR(190) NOT NULL, token VARCHAR(64) NOT NULL, status ENUM('pending','accepted','expired') NOT NULL DEFAULT 'pending', invited_by INT UNSIGNED NULL, expires_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_invite_tenant(tenant_id), CONSTRAINT fk_invite_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_invite_team FOREIGN KEY(team_id) REFERENCES teams(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE milestones (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, project_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NULL, due_date DATE NULL, is_completed TINYINT(1) NOT NULL DEFAULT 0, completed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ms_tenant(tenant_id), INDEX idx_ms_project(project_id), CONSTRAINT fk_ms_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_ms_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE time_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, project_id INT UNSIGNED NULL, task_id INT UNSIGNED NULL, user_id INT UNSIGNED NOT NULL, started_at DATETIME NOT NULL, ended_at DATETIME NULL, minutes INT NULL, is_billable TINYINT(1) NOT NULL DEFAULT 1, notes VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tl_tenant(tenant_id), INDEX idx_tl_project(project_id), INDEX idx_tl_user(user_id), CONSTRAINT fk_tl_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_tl_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL, CONSTRAINT fk_tl_task FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE SET NULL, CONSTRAINT fk_tl_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NULL, event_date DATE NOT NULL, project_id INT UNSIGNED NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ev_tenant(tenant_id), INDEX idx_ev_date(event_date), CONSTRAINT fk_ev_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_ev_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE activities (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, description VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_act_tenant(tenant_id)) ENGINE=InnoDB;
CREATE TABLE notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, title VARCHAR(180) NOT NULL, body TEXT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_notif_user(user_id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(80) NULL, entity_id INT NULL, ip_address VARCHAR(45) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_tenant(tenant_id)) ENGINE=InnoDB;
CREATE TABLE support_tickets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, subject VARCHAR(200) NOT NULL, message TEXT NOT NULL, status ENUM('open','in_progress','resolved','closed') NOT NULL DEFAULT 'open', priority ENUM('low','medium','high') NOT NULL DEFAULT 'medium', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ticket_tenant(tenant_id)) ENGINE=InnoDB;
CREATE TABLE announcements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, setting_key VARCHAR(80) NOT NULL, setting_value TEXT NULL, UNIQUE KEY uq_settings (tenant_id,setting_key)) ENGINE=InnoDB;

